import { useCallback, useMemo } from "react";
import { ColumnsSettingsStorage } from "../../dataGrid/withFlexibleColumns/flexibleColumnsStorage";
export const useSettingsStorage = (pageName, storage) => {
    const settingsStorage = useMemo(() => storage || new ColumnsSettingsStorage(pageName || "", localStorage), [pageName, storage]);
    const saveSettingsToTheStorage = useCallback((newSettings) => 
    // not to block main thread this operation can be postponed
    new Promise((resolve, reject) => {
        setTimeout(() => {
            try {
                settingsStorage.setItem(newSettings);
                resolve();
            }
            catch (e) {
                reject(e);
            }
        }, 0);
    }), [settingsStorage]);
    return { settingsStorage, saveSettingsToTheStorage };
};
